// Verus program: rotate an array (Vec<u32>) to the right by n positions.
// The result is a fresh Vec with the same length, equal to
// list[s..len] followed by list[0..s], where s = len - (n mod len).

#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

spec fn rotated_right_spec(list: Seq<u32>, n: nat) -> Seq<u32>
    recommends
        list.len() > 0,
{
    let len = list.len();
    let k = n % len;
    let s = len - k;
    // Concatenation of suffix then prefix
    list.subrange(s, len) + list.subrange(0, s)
}

fn rotate_right(list: &Vec<u32>, n: usize) -> (new_list: Vec<u32>)
    requires
        list.len() > 0,
    ensures
        new_list.len() == list.len(),
        new_list@ == rotated_right_spec(list@, n as nat),
{
    let len: usize = list.len();
    let k: usize = n % len;      // safe since len > 0 (by requires)
    let s: usize = len - k;      // in [0, len]

    let mut out: Vec<u32> = Vec::new();

    // First copy the suffix: list[s..len)
    let mut i: usize = s;
    while i < len
        invariant
            len == list.len(),
            s <= len,
            i <= len,
            s <= i,
            out.len() == i - s,
            out@ == list@.subrange(s as int, i as int),
        decreases
            len - i,
    {
        out.push(list[i]);
        i += 1;
    }

    // Then copy the prefix: list[0..s)
    let mut j: usize = 0;
    while j < s
        invariant
            len == list.len(),
            s <= len,
            j <= s,
            out.len() == (len - s) + j,
            out@ == list@.subrange(s as int, len as int) + list@.subrange(0 as int, j as int),
        decreases
            s - j,
    {
        out.push(list[j]);
        j += 1;
    }

    proof {
        // Establish the final postcondition in the same shape as the spec.
        // Also relate k/s to the spec definition.
        assert(out.len() == len);
        assert((n as nat) % (len as nat) == k as nat);
        assert(s as nat == (len as nat) - ((n as nat) % (len as nat)));
        assert(out@ == list@.subrange(s as int, len as int) + list@.subrange(0 as int, s as int));
    }

    out
}

} // verus!